struct name_to_number_map
{
    typedef pair<const charstarwrap, unsigned int> value_type;
    rb_node *header;
    unsigned int count;
    bool key_compare;
    char padding[3];

    name_to_number_map()
    {
        header = static_cast<rb_node *>(arch_malloc(24, __FILE__, 0));
        if (!header)
            header = static_cast<rb_node *>(oom_malloc(24));
        count = 0;
        key_compare = false;
        header->color = 0;
        header->parent = 0;
        header->left = header;
        header->right = header;
    }

    void clear()
    {
        if (count)
        {
            rb_erase(this, header->parent);
            header->left = header;
            header->parent = 0;
            header->right = header;
            count = 0;
        }
    }

    pair<rb_node *, bool> insert(const value_type &value)
    {
        return rb_insert(this, value);
    }
};

class singleton
