protected:
    singleton() {}
    virtual ~singleton();
};

class entity_manager : name_to_number_map, public singleton
{
    name_to_number_map name_to_number;
    int number_server;
public:
    entity_manager();
};

entity_manager::entity_manager() : number_server( 0 )
{
  name_to_number.clear();
  number_server = 0;
